mod support;

use base64::{Engine, engine::general_purpose::STANDARD};
use cyclops_sdk::{
    CreateRegistrySecretRequest, CyclopsClient, CyclopsConfiguration, CyclopsCredentials,
    HttpResponse, RegistrySecret, SdkError, registry_secret_name_prefix,
};
use std::sync::Arc;
use support::ScriptedHttpClient;

const BASE_URL: &str = "https://cyclops.example:8443/prefix";
const TOKEN_URL: &str = "https://identity.example/oauth/token";
const SECRETS: &str =
    "https://cyclops.example:8443/prefix/api/k8s/api/v1/namespaces/example-pool/secrets";

fn request() -> CreateRegistrySecretRequest {
    CreateRegistrySecretRequest {
        namespace: "example-pool".into(),
        name: "cua-registry-ghcr".into(),
        registry: "ghcr.io".into(),
        username: "octo".into(),
        password: "ghp_token".into(),
    }
}

#[tokio::test]
async fn create_registry_secret_posts_a_dockerconfigjson_secret() {
    let http = Arc::new(ScriptedHttpClient::new([
        Ok(token()),
        Ok(response(201, br#"{"kind":"Secret"}"#)),
    ]));

    let secret = client(Arc::clone(&http))
        .create_registry_secret(request())
        .await
        .unwrap();

    assert_eq!(
        secret,
        RegistrySecret {
            namespace: "example-pool".into(),
            name: "cua-registry-ghcr".into(),
            registry: "ghcr.io".into(),
        }
    );
    let requests = http.authenticated_requests().await;
    assert_eq!(requests.len(), 1);
    assert_eq!(requests[0].method, "POST");
    assert_eq!(requests[0].url, SECRETS);
    let body: serde_json::Value =
        serde_json::from_slice(requests[0].body.as_deref().unwrap()).unwrap();
    assert_eq!(body["type"], "kubernetes.io/dockerconfigjson");
    assert_eq!(body["metadata"]["name"], "cua-registry-ghcr");
    assert_eq!(body["metadata"]["namespace"], "example-pool");
    assert!(body["metadata"].get("annotations").is_none());
    assert!(body.get("stringData").is_none());
    let config: serde_json::Value = serde_json::from_slice(
        &STANDARD
            .decode(body["data"][".dockerconfigjson"].as_str().unwrap())
            .unwrap(),
    )
    .unwrap();
    let auth = &config["auths"]["ghcr.io"];
    assert_eq!(auth["username"], "octo");
    assert_eq!(auth["password"], "ghp_token");
    assert_eq!(auth["auth"], STANDARD.encode("octo:ghp_token"));
}

#[tokio::test]
async fn create_registry_secret_replaces_an_existing_secret() {
    let http = Arc::new(ScriptedHttpClient::new([
        Ok(token()),
        Ok(response(409, br#"{"reason":"AlreadyExists"}"#)),
        Ok(response(200, b"{}")),
        Ok(response(201, b"{}")),
    ]));

    client(Arc::clone(&http))
        .create_registry_secret(request())
        .await
        .unwrap();

    let requests = http.authenticated_requests().await;
    let calls: Vec<_> = requests
        .iter()
        .map(|request| (request.method.as_str(), request.url.as_str()))
        .collect();
    let item = format!("{SECRETS}/cua-registry-ghcr");
    assert_eq!(
        calls,
        vec![
            ("POST", SECRETS),
            ("DELETE", item.as_str()),
            ("POST", SECRETS)
        ]
    );
}

#[tokio::test]
async fn registry_secret_names_and_hosts_are_validated_before_any_request() {
    for (mutate, needle) in [
        (
            (|request: &mut CreateRegistrySecretRequest| request.name = "ecr-credentials".into())
                as fn(&mut CreateRegistrySecretRequest),
            "must start with cua-registry-",
        ),
        (
            |request: &mut CreateRegistrySecretRequest| request.name = "cua-registry-".into(),
            "registry secret name",
        ),
        (
            |request: &mut CreateRegistrySecretRequest| request.registry = "https://ghcr.io".into(),
            "bare host",
        ),
        (
            |request: &mut CreateRegistrySecretRequest| request.password = String::new(),
            "must not be empty",
        ),
    ] {
        let http = Arc::new(ScriptedHttpClient::new([Ok(token())]));
        let mut request = request();
        mutate(&mut request);
        let error = client(Arc::clone(&http))
            .create_registry_secret(request)
            .await
            .unwrap_err();
        let matched = match &error {
            SdkError::Configuration { reason } => reason.contains(needle),
            SdkError::InvalidResourceName { field, .. } => field.contains(needle),
            _ => false,
        };
        assert!(matched, "{error:?}");
        assert!(http.authenticated_requests().await.is_empty());
    }
}

#[test]
fn registry_secret_request_debug_redacts_the_password() {
    let debug = format!("{:?}", request());
    assert!(!debug.contains("ghp_token"));
    assert!(debug.contains("<redacted>"));
    assert_eq!(registry_secret_name_prefix(), "cua-registry-");
}

#[tokio::test]
async fn delete_registry_secret_targets_the_item_and_tolerates_404() {
    let http = Arc::new(ScriptedHttpClient::new([
        Ok(token()),
        Ok(response(404, b"{}")),
    ]));

    client(Arc::clone(&http))
        .delete_registry_secret("example-pool".into(), "cua-registry-ghcr".into())
        .await
        .unwrap();

    let requests = http.authenticated_requests().await;
    assert_eq!(requests[0].method, "DELETE");
    assert_eq!(requests[0].url, format!("{SECRETS}/cua-registry-ghcr"));
}

#[tokio::test]
async fn resolve_image_queries_the_gateway_and_decodes_the_pin() {
    let digest = format!("sha256:{}", "a".repeat(64));
    let http = Arc::new(ScriptedHttpClient::new([
        Ok(token()),
        Ok(response(
            200,
            serde_json::json!({
                "ref": "ghcr.io/trycua/linux:24.04",
                "resolvedRef": "ghcr.io/trycua/linux:24.04-disk",
                "pinnedRef": format!("ghcr.io/trycua/linux@{digest}"),
                "digest": digest,
                "variant": "containerdisk",
                "platformDigest": null,
                "mediaType": "application/vnd.oci.image.index.v1+json",
            })
            .to_string()
            .as_bytes(),
        )),
    ]));

    let resolved = client(Arc::clone(&http))
        .resolve_image("ghcr.io/trycua/linux:24.04".into(), Some("kubevirt".into()))
        .await
        .unwrap();

    assert_eq!(resolved.variant, "containerdisk");
    assert_eq!(resolved.resolved_ref, "ghcr.io/trycua/linux:24.04-disk");
    let requests = http.authenticated_requests().await;
    assert_eq!(
        requests[0].url,
        "https://cyclops.example:8443/prefix/api/images/resolve?ref=ghcr.io%2Ftrycua%2Flinux%3A24.04&runtime=kubevirt"
    );

    let error = client(Arc::new(ScriptedHttpClient::new([Ok(token())])))
        .resolve_image("ghcr.io/x".into(), Some("docker".into()))
        .await
        .unwrap_err();
    assert!(matches!(error, SdkError::Configuration { .. }));
}

fn client(http: Arc<ScriptedHttpClient>) -> Arc<CyclopsClient> {
    CyclopsClient::connect(
        CyclopsConfiguration {
            base_url: BASE_URL.into(),
            token_url: TOKEN_URL.into(),
            credentials: CyclopsCredentials::new("client".into(), "secret".into()),
            pool_poll_interval_ms: 1,
            pool_poll_limit: 1,
            claim_poll_interval_ms: 1,
            claim_poll_limit: 1,
        },
        http,
    )
    .unwrap()
}

fn token() -> HttpResponse {
    response(200, br#"{"access_token":"token-a","expires_in":3600}"#)
}

fn response(status: u16, body: &[u8]) -> HttpResponse {
    HttpResponse {
        status,
        headers: Vec::new(),
        body: body.to_vec(),
    }
}

mod support;

use cyclops_sdk::{
    AccessTokenProvider, AccessTokenProviderError, CyclopsClient, CyclopsConfiguration,
    CyclopsCredentials, CyclopsTokenProviderConfiguration, HttpError, HttpHeader, HttpRequest,
    HttpResponse, SdkError,
};
use std::{collections::VecDeque, sync::Arc};
use support::ScriptedHttpClient;
use tokio::sync::Mutex;

const BASE_URL: &str = "https://cyclops.example:8443/api";
const TOKEN_URL: &str = "https://identity.example/oauth/token";

#[tokio::test]
async fn caches_token_until_expiry_and_encodes_credentials() {
    let http = Arc::new(ScriptedHttpClient::new([
        Ok(token("token-a", 3600)),
        Ok(response(200, b"first")),
        Ok(response(200, b"second")),
    ]));
    let client = client(Arc::clone(&http));

    assert_eq!(
        client
            .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
            .await
            .unwrap()
            .body,
        b"first"
    );
    assert_eq!(
        client
            .execute_authenticated(request("https://cyclops.example:8443/api/claims"))
            .await
            .unwrap()
            .body,
        b"second"
    );

    let requests = http.requests().await;
    assert_eq!(requests.len(), 3);
    assert_eq!(requests[0].url, TOKEN_URL);
    assert_eq!(requests[0].method, "POST");
    assert_eq!(
        requests[0].body,
        Some(b"grant_type=client_credentials".to_vec())
    );
    assert_eq!(
        requests[0].headers,
        vec![
            header("accept", "application/json"),
            header("content-type", "application/x-www-form-urlencoded"),
            header(
                "authorization",
                "Basic Y2xpZW50IGlkKy8lOnNlY3JldCAmPSsvJQ=="
            ),
        ]
    );
    assert_bearer(&requests[1], "token-a");
    assert_bearer(&requests[2], "token-a");
    assert_eq!(
        requests[1].headers,
        vec![
            header("x-intent", "preserve-order"),
            header("x-trace", "keep"),
            header("authorization", "Bearer token-a"),
        ]
    );
}

#[tokio::test]
async fn refreshes_a_token_at_the_expiry_skew() {
    let http = Arc::new(ScriptedHttpClient::new([
        Ok(token("token-a", 30)),
        Ok(response(200, b"first")),
        Ok(token("token-b", 3600)),
        Ok(response(200, b"second")),
    ]));
    let client = client(Arc::clone(&http));

    client
        .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
        .await
        .unwrap();
    client
        .execute_authenticated(request("https://cyclops.example:8443/api/claims"))
        .await
        .unwrap();

    let requests = http.requests().await;
    assert_eq!(
        requests
            .iter()
            .filter(|request| request.url == TOKEN_URL)
            .count(),
        2
    );
    assert_bearer(&requests[1], "token-a");
    assert_bearer(&requests[3], "token-b");
}

#[tokio::test]
async fn concurrent_cache_misses_fetch_one_token() {
    let http = Arc::new(ScriptedHttpClient::new([]));
    let blocked_token = http.enqueue_blocking(Ok(token("token-a", 3600))).await;
    http.enqueue(Ok(response(200, b"first"))).await;
    http.enqueue(Ok(response(200, b"second"))).await;
    let client = client(Arc::clone(&http));

    let first = tokio::spawn({
        let client = Arc::clone(&client);
        async move {
            client
                .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
                .await
        }
    });
    blocked_token.wait_until_started().await;
    let second = tokio::spawn({
        let client = Arc::clone(&client);
        async move {
            client
                .execute_authenticated(request("https://cyclops.example:8443/api/claims"))
                .await
        }
    });

    tokio::task::yield_now().await;
    assert_eq!(
        http.requests().await.len(),
        1,
        "only one token request is in flight"
    );
    blocked_token.release();
    assert_eq!(first.await.unwrap().unwrap().body, b"first");
    assert_eq!(second.await.unwrap().unwrap().body, b"second");

    let requests = http.requests().await;
    assert_eq!(requests.len(), 3);
    assert_eq!(
        requests
            .iter()
            .filter(|request| request.url == TOKEN_URL)
            .count(),
        1
    );
}

#[tokio::test]
async fn delayed_unauthorized_does_not_invalidate_same_value_newer_generation() {
    let http = Arc::new(ScriptedHttpClient::new([Ok(token("shared-token", 3600))]));
    let delayed_unauthorized = http.enqueue_blocking(Ok(response(401, b"expired-a"))).await;
    http.enqueue(Ok(response(401, b"expired-b"))).await;
    http.enqueue(Ok(token("shared-token", 3600))).await;
    http.enqueue(Ok(response(200, b"retried-b"))).await;
    http.enqueue(Ok(response(200, b"retried-a"))).await;
    let client = client(Arc::clone(&http));

    let request_a = tokio::spawn({
        let client = Arc::clone(&client);
        async move {
            client
                .execute_authenticated(request("https://cyclops.example:8443/api/pools/a"))
                .await
        }
    });
    delayed_unauthorized.wait_until_started().await;

    let response_b = client
        .execute_authenticated(request("https://cyclops.example:8443/api/pools/b"))
        .await
        .unwrap();
    assert_eq!(response_b.body, b"retried-b");

    delayed_unauthorized.release();
    let response_a = request_a.await.unwrap().unwrap();
    assert_eq!(response_a.body, b"retried-a");

    let requests = http.requests().await;
    assert_eq!(
        requests
            .iter()
            .filter(|request| request.url == TOKEN_URL)
            .count(),
        2,
        "a delayed 401 must not clear a newer same-value token generation"
    );
    assert_eq!(requests.len(), 6);
}

#[tokio::test]
async fn refreshes_once_after_unauthorized() {
    let http = Arc::new(ScriptedHttpClient::new([
        Ok(token("token-a", 3600)),
        Ok(response(401, b"expired")),
        Ok(token("token-b", 3600)),
        Ok(response(200, b"ok")),
    ]));
    let client = client(Arc::clone(&http));

    assert_eq!(
        client
            .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
            .await
            .unwrap()
            .body,
        b"ok"
    );

    let requests = http.requests().await;
    assert_eq!(requests.len(), 4);
    assert_bearer(&requests[1], "token-a");
    assert_bearer(&requests[3], "token-b");
}

#[tokio::test]
async fn provider_token_is_used_without_calling_the_token_endpoint() {
    let http = Arc::new(ScriptedHttpClient::new([Ok(response(200, b"ok"))]));
    let provider = Arc::new(ScriptedAccessTokenProvider::new([Ok(
        "browser-token".into()
    )]));
    let client = provider_client(Arc::clone(&http), provider);

    assert_eq!(
        client
            .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
            .await
            .unwrap()
            .body,
        b"ok"
    );

    let requests = http.requests().await;
    assert_eq!(requests.len(), 1);
    assert_bearer(&requests[0], "browser-token");
}

#[tokio::test]
async fn provider_is_forced_to_refresh_once_after_a_control_plane_401() {
    let http = Arc::new(ScriptedHttpClient::new([
        Ok(response(401, b"expired")),
        Ok(response(200, b"ok")),
    ]));
    let provider = Arc::new(ScriptedAccessTokenProvider::new([
        Ok("browser-token-a".into()),
        Ok("browser-token-b".into()),
    ]));
    let client = provider_client(Arc::clone(&http), Arc::clone(&provider));

    assert_eq!(
        client
            .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
            .await
            .unwrap()
            .body,
        b"ok"
    );

    assert_eq!(provider.refresh_requests().await, vec![false, true]);
    let requests = http.requests().await;
    assert_eq!(requests.len(), 2);
    assert_bearer(&requests[0], "browser-token-a");
    assert_bearer(&requests[1], "browser-token-b");
}

#[tokio::test]
async fn provider_error_and_empty_token_are_reported_as_token_errors() {
    let provider_error = Arc::new(ScriptedAccessTokenProvider::new([Err(
        AccessTokenProviderError::Failed {
            reason: "browser session expired".into(),
        },
    )]));
    let error = provider_client(Arc::new(ScriptedHttpClient::new([])), provider_error)
        .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
        .await
        .unwrap_err();
    assert!(matches!(error, SdkError::Token { .. }));

    let empty_token = Arc::new(ScriptedAccessTokenProvider::new([Ok("  \n\t".into())]));
    let error = provider_client(Arc::new(ScriptedHttpClient::new([])), empty_token)
        .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
        .await
        .unwrap_err();
    assert!(matches!(error, SdkError::Token { .. }));
}

#[tokio::test]
async fn does_not_retry_a_second_unauthorized() {
    let http = Arc::new(ScriptedHttpClient::new([
        Ok(token("token-a", 3600)),
        Ok(response(401, b"expired")),
        Ok(token("token-b", 3600)),
        Ok(response(401, b"still expired")),
    ]));
    let client = client(Arc::clone(&http));

    let error = client
        .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
        .await
        .unwrap_err();
    assert!(matches!(error, SdkError::Status { status: 401, .. }));
    assert_eq!(http.requests().await.len(), 4);
}

#[tokio::test]
async fn maps_oauth_errors_and_invalid_json() {
    let status_http = Arc::new(ScriptedHttpClient::new([Ok(response(503, b"unavailable"))]));
    let error = client(status_http)
        .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
        .await
        .unwrap_err();
    assert!(
        matches!(error, SdkError::Status { operation, status: 503, .. } if operation == "acquire OAuth token")
    );

    let invalid_json_http = Arc::new(ScriptedHttpClient::new([Ok(response(200, b"not json"))]));
    let error = client(invalid_json_http)
        .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
        .await
        .unwrap_err();
    assert!(matches!(error, SdkError::Token { .. }));

    let callback_http = Arc::new(ScriptedHttpClient::new([Err(HttpError::Transport {
        reason: "offline".into(),
    })]));
    let error = client(callback_http)
        .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
        .await
        .unwrap_err();
    assert!(matches!(error, SdkError::Transport { reason } if reason == "offline"));
}

#[tokio::test]
async fn does_not_attach_bearer_to_cross_origin_requests() {
    let http = Arc::new(ScriptedHttpClient::new([Ok(response(200, b"external"))]));
    let client = client(Arc::clone(&http));
    let external = HttpRequest {
        method: "GET".into(),
        url: "https://cyclops.example/api/pools".into(),
        headers: vec![header("Authorization", "Basic external")],
        body: Some(vec![0, 1, 2]),
        timeout_secs: None,
        max_response_bytes: None,
    };

    let response = client.execute_authenticated(external).await.unwrap();
    assert_eq!(response.body, b"external");
    let requests = http.requests().await;
    assert_eq!(requests.len(), 1);
    assert_eq!(
        requests[0].headers,
        vec![header("Authorization", "Basic external")]
    );
    assert_eq!(requests[0].body, Some(vec![0, 1, 2]));
}

fn client(http: Arc<ScriptedHttpClient>) -> Arc<CyclopsClient> {
    CyclopsClient::connect(
        CyclopsConfiguration {
            base_url: BASE_URL.into(),
            token_url: TOKEN_URL.into(),
            credentials: CyclopsCredentials::new("client id+/%".into(), "secret &=+/%".into()),
            pool_poll_interval_ms: 1,
            pool_poll_limit: 1,
            claim_poll_interval_ms: 1,
            claim_poll_limit: 1,
        },
        http,
    )
    .unwrap()
}

fn provider_client(
    http: Arc<ScriptedHttpClient>,
    provider: Arc<ScriptedAccessTokenProvider>,
) -> Arc<CyclopsClient> {
    CyclopsClient::connect_with_access_token_provider(
        CyclopsTokenProviderConfiguration {
            base_url: BASE_URL.into(),
            pool_poll_interval_ms: 1,
            pool_poll_limit: 1,
            claim_poll_interval_ms: 1,
            claim_poll_limit: 1,
        },
        provider,
        http,
    )
    .unwrap()
}

struct ScriptedAccessTokenProvider {
    values: Mutex<VecDeque<Result<String, AccessTokenProviderError>>>,
    refresh_requests: Mutex<Vec<bool>>,
}

impl ScriptedAccessTokenProvider {
    fn new(values: impl IntoIterator<Item = Result<String, AccessTokenProviderError>>) -> Self {
        Self {
            values: Mutex::new(values.into_iter().collect()),
            refresh_requests: Mutex::new(Vec::new()),
        }
    }

    async fn refresh_requests(&self) -> Vec<bool> {
        self.refresh_requests.lock().await.clone()
    }
}

#[async_trait::async_trait]
impl AccessTokenProvider for ScriptedAccessTokenProvider {
    async fn get_access_token(
        &self,
        force_refresh: bool,
    ) -> Result<String, AccessTokenProviderError> {
        self.refresh_requests.lock().await.push(force_refresh);
        self.values
            .lock()
            .await
            .pop_front()
            .expect("access-token provider called more than scripted")
    }
}

fn request(url: &str) -> HttpRequest {
    HttpRequest {
        method: "GET".into(),
        url: url.into(),
        headers: vec![
            header("x-intent", "preserve-order"),
            header("Authorization", "Bearer caller-token"),
            header("x-trace", "keep"),
        ],
        body: None,
        timeout_secs: None,
        max_response_bytes: None,
    }
}

fn token(value: &str, expires_in: u64) -> HttpResponse {
    response(
        200,
        format!(r#"{{"access_token":"{value}","expires_in":{expires_in}}}"#).as_bytes(),
    )
}

fn response(status: u16, body: &[u8]) -> HttpResponse {
    HttpResponse {
        status,
        headers: vec![],
        body: body.to_vec(),
    }
}

fn header(name: &str, value: &str) -> HttpHeader {
    HttpHeader {
        name: name.into(),
        value: value.into(),
    }
}

fn assert_bearer(request: &HttpRequest, token: &str) {
    assert_eq!(
        request
            .headers
            .iter()
            .filter(|header| header.name.eq_ignore_ascii_case("authorization"))
            .count(),
        1
    );
    assert_eq!(
        request
            .headers
            .iter()
            .find(|header| header.name.eq_ignore_ascii_case("authorization"))
            .unwrap()
            .value,
        format!("Bearer {token}")
    );
}

#[tokio::test]
async fn static_access_token_is_used_without_token_provider_callback() {
    let http = Arc::new(ScriptedHttpClient::new([Ok(response(200, b"ok"))]));
    let client = static_token_client(Arc::clone(&http), "browser-token");

    assert_eq!(
        client
            .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
            .await
            .unwrap()
            .body,
        b"ok"
    );

    let requests = http.requests().await;
    assert_eq!(requests.len(), 1);
    assert_bearer(&requests[0], "browser-token");
}

fn static_token_client(http: Arc<ScriptedHttpClient>, access_token: &str) -> Arc<CyclopsClient> {
    CyclopsClient::connect_with_access_token(
        CyclopsTokenProviderConfiguration {
            base_url: BASE_URL.into(),
            pool_poll_interval_ms: 1,
            pool_poll_limit: 1,
            claim_poll_interval_ms: 1,
            claim_poll_limit: 1,
        },
        access_token.into(),
        http,
    )
    .unwrap()
}

#[tokio::test]
async fn static_access_token_is_not_retried_after_a_401() {
    let http = Arc::new(ScriptedHttpClient::new([Ok(response(401, b"expired"))]));
    let client = static_token_client(Arc::clone(&http), "browser-token");

    let error = client
        .execute_authenticated(request("https://cyclops.example:8443/api/pools"))
        .await
        .unwrap_err();
    assert!(
        matches!(error, SdkError::Token { reason } if reason.contains("static access token was rejected"))
    );
    assert_eq!(http.requests().await.len(), 1);
}

#![allow(dead_code)]

use async_trait::async_trait;
use cyclops_sdk::{HttpClient, HttpError, HttpRequest, HttpResponse};
use std::{collections::VecDeque, sync::Arc};
use tokio::sync::{Mutex, Notify};

pub struct ScriptedHttpClient {
    requests: Mutex<Vec<HttpRequest>>,
    responses: Mutex<VecDeque<QueuedResponse>>,
}

enum QueuedResponse {
    Immediate(Result<HttpResponse, HttpError>),
    Blocking {
        response: Result<HttpResponse, HttpError>,
        started: Arc<Notify>,
        release: Arc<Notify>,
    },
}

pub struct BlockedResponse {
    started: Arc<Notify>,
    release: Arc<Notify>,
}

impl ScriptedHttpClient {
    pub fn new(responses: impl IntoIterator<Item = Result<HttpResponse, HttpError>>) -> Self {
        Self {
            requests: Mutex::new(Vec::new()),
            responses: Mutex::new(
                responses
                    .into_iter()
                    .map(QueuedResponse::Immediate)
                    .collect(),
            ),
        }
    }

    pub async fn enqueue(&self, response: Result<HttpResponse, HttpError>) {
        self.responses
            .lock()
            .await
            .push_back(QueuedResponse::Immediate(response));
    }

    pub async fn enqueue_blocking(
        &self,
        response: Result<HttpResponse, HttpError>,
    ) -> BlockedResponse {
        let started = Arc::new(Notify::new());
        let release = Arc::new(Notify::new());
        self.responses
            .lock()
            .await
            .push_back(QueuedResponse::Blocking {
                response,
                started: Arc::clone(&started),
                release: Arc::clone(&release),
            });
        BlockedResponse { started, release }
    }

    pub async fn requests(&self) -> Vec<HttpRequest> {
        self.requests.lock().await.clone()
    }

    pub async fn request_count(&self) -> usize {
        self.requests.lock().await.len()
    }

    pub async fn authenticated_requests(&self) -> Vec<HttpRequest> {
        self.requests().await.into_iter().skip(1).collect()
    }
}

impl BlockedResponse {
    pub async fn wait_until_started(&self) {
        self.started.notified().await;
    }

    pub fn release(&self) {
        self.release.notify_one();
    }
}

#[async_trait]
impl HttpClient for ScriptedHttpClient {
    async fn execute(&self, request: HttpRequest) -> Result<HttpResponse, HttpError> {
        self.requests.lock().await.push(request);
        let response = {
            self.responses
                .lock()
                .await
                .pop_front()
                .expect("scripted HTTP client received an unexpected request")
        };
        match response {
            QueuedResponse::Immediate(response) => response,
            QueuedResponse::Blocking {
                response,
                started,
                release,
            } => {
                started.notify_one();
                release.notified().await;
                response
            }
        }
    }
}

//! Tenant-owned registry pull Secrets and server-side image resolution.
//!
//! A private registry image needs a pull Secret in the pool namespace. The
//! gateway lets a tenant create exactly one kind of Secret for that: a
//! `kubernetes.io/dockerconfigjson` Secret named `cua-registry-<name>` and
//! labeled `cua.ai/registry-secret: "true"`
//! (`cyclops-cs/backend/auth/tenant_secret_admission.rego`). Secrets are
//! write-only through the gateway: no read, list or update, so a credential
//! cannot be read back, and "update" is delete + create.
//!
//! Reference the Secret from `vmTemplate.imagePullSecret`; the pod runtimes
//! put it in the pod's `imagePullSecrets` (sidecar images included) and
//! KubeVirt uses it for the containerDisk pull.

use crate::{CyclopsClient, HttpHeader, HttpRequest, SdkError, routes};
use base64::{Engine, engine::general_purpose::STANDARD};
use cyclops_sdk_schema::REGISTRY_SECRET_NAME_PREFIX;
use serde::{Deserialize, Serialize};
use std::{fmt, sync::Arc};

const JSON_CONTENT_TYPE: &str = "application/json";
const DOCKER_CONFIG_JSON_TYPE: &str = "kubernetes.io/dockerconfigjson";
const DOCKER_CONFIG_JSON_KEY: &str = ".dockerconfigjson";

/// Credentials for one registry, stored as a `cua-registry-*` pull Secret.
#[derive(Clone, uniffi::Record, uniffi_builder_derive::UniffiBuilder)]
#[uniffi_builder(crate::SdkBuildError)]
pub struct CreateRegistrySecretRequest {
    /// Pool namespace the Secret is created in. It must already exist (the
    /// pool's namespace, created by `create_pool`, or by `create_namespace`).
    pub namespace: String,
    /// Full Secret name, `cua-registry-<dns-label>`.
    pub name: String,
    /// Registry host the credentials are for, as image refs spell it, e.g.
    /// `ghcr.io`, `registry.example.com:5000` or `docker.io`.
    pub registry: String,
    pub username: String,
    /// Password or access token. Never serialized by `Debug`.
    pub password: String,
}

impl fmt::Debug for CreateRegistrySecretRequest {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("CreateRegistrySecretRequest")
            .field("namespace", &self.namespace)
            .field("name", &self.name)
            .field("registry", &self.registry)
            .field("username", &self.username)
            .field("password", &"<redacted>")
            .finish()
    }
}

/// A created registry pull Secret. Carries no credential: Secrets are
/// write-only through the gateway.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, uniffi::Record)]
pub struct RegistrySecret {
    pub namespace: String,
    pub name: String,
    pub registry: String,
}

/// A registry ref pinned by the gateway (`GET /api/images/resolve`).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, uniffi::Record)]
#[serde(rename_all = "camelCase")]
pub struct ResolvedImage {
    /// The ref as requested.
    #[serde(rename = "ref")]
    pub reference: String,
    /// The ref actually resolved: for a canonical image and runtime
    /// `kubevirt` this is the containerDisk sibling (`…:24.04-disk`).
    pub resolved_ref: String,
    /// `repo@sha256:…` of the manifest (or index) to run.
    pub pinned_ref: String,
    pub digest: String,
    /// `rootfs` (docker/gVisor), `containerdisk` (KubeVirt), `lume` (macOS)
    /// or `unknown`.
    pub variant: String,
    /// The linux/amd64 child manifest digest when the ref is an index.
    #[serde(default)]
    pub platform_digest: Option<String>,
    pub media_type: String,
}

/// The name prefix every tenant registry pull Secret must carry.
#[uniffi::export]
pub fn registry_secret_name_prefix() -> String {
    REGISTRY_SECRET_NAME_PREFIX.into()
}

#[uniffi::export]
impl CyclopsClient {
    /// Create (or replace) a `cua-registry-*` dockerconfigjson pull Secret.
    /// On a name conflict the old Secret is deleted and the new one created,
    /// since the gateway admits no Secret update.
    pub async fn create_registry_secret(
        self: Arc<Self>,
        request: CreateRegistrySecretRequest,
    ) -> Result<RegistrySecret, SdkError> {
        let collection_url =
            routes::registry_secret_collection(self.base_url(), &request.namespace)?;
        let item_url =
            routes::registry_secret_item(self.base_url(), &request.namespace, &request.name)?;
        let body = registry_secret_body(&request)?;

        let created = self
            .send_allowed(
                "create registry secret",
                json_request("POST", collection_url.clone(), Some(body.clone())),
                &[200, 201, 202, 409],
            )
            .await?;
        if created.status == 409 {
            self.send_unit_crud(
                "replace registry secret",
                json_request("DELETE", item_url, None),
                &[200, 202, 204, 404],
            )
            .await?;
            self.send_unit_crud(
                "create registry secret",
                json_request("POST", collection_url, Some(body)),
                &[200, 201, 202],
            )
            .await?;
        }
        Ok(RegistrySecret {
            namespace: request.namespace,
            name: request.name,
            registry: request.registry,
        })
    }

    pub async fn delete_registry_secret(
        self: Arc<Self>,
        namespace: String,
        name: String,
    ) -> Result<(), SdkError> {
        let item_url = routes::registry_secret_item(self.base_url(), &namespace, &name)?;
        self.send_unit_crud(
            "delete registry secret",
            json_request("DELETE", item_url, None),
            &[200, 202, 204, 404],
        )
        .await
    }

    /// Pin a public registry ref to a digest server-side. `runtime` (`gvisor`,
    /// `kubevirt`, `macos`) selects the variant for canonical cua images:
    /// `kubevirt` maps `ghcr.io/trycua/linux:24.04` to its `-disk` sibling.
    pub async fn resolve_image(
        self: Arc<Self>,
        reference: String,
        runtime: Option<String>,
    ) -> Result<ResolvedImage, SdkError> {
        let url = routes::image_resolve(self.base_url(), &reference, runtime.as_deref())?;
        self.send_json_crud("resolve image", json_request("GET", url, None), &[200])
            .await
    }
}

pub(crate) fn validate_registry_secret_name(name: &str) -> Result<(), SdkError> {
    let rest = name
        .strip_prefix(REGISTRY_SECRET_NAME_PREFIX)
        .ok_or_else(|| SdkError::Configuration {
            reason: format!("registry secret name must start with {REGISTRY_SECRET_NAME_PREFIX}"),
        })?;
    routes::validate_dns_label_for("registry secret name", rest)?;
    if name.len() > 253 {
        return Err(SdkError::Configuration {
            reason: "registry secret name must be at most 253 characters".into(),
        });
    }
    Ok(())
}

fn validate_registry_host(registry: &str) -> Result<(), SdkError> {
    let invalid = registry.is_empty()
        || registry.len() > 255
        || registry.contains("://")
        || registry.contains('/')
        || registry
            .bytes()
            .any(|byte| byte.is_ascii_whitespace() || byte.is_ascii_control());
    if invalid {
        return Err(SdkError::Configuration {
            reason: "registry must be a bare host[:port] such as ghcr.io".into(),
        });
    }
    Ok(())
}

/// The Secret body the gateway admits: exactly the dockerconfigjson shape,
/// with no annotations, owner references or generateName.
pub(crate) fn registry_secret_body(
    request: &CreateRegistrySecretRequest,
) -> Result<Vec<u8>, SdkError> {
    validate_registry_secret_name(&request.name)?;
    validate_registry_host(&request.registry)?;
    if request.username.is_empty() || request.password.is_empty() {
        return Err(SdkError::Configuration {
            reason: "registry username and password must not be empty".into(),
        });
    }
    let auth = STANDARD.encode(format!("{}:{}", request.username, request.password));
    let docker_config = serde_json::json!({
        "auths": {
            request.registry.clone(): {
                "username": request.username,
                "password": request.password,
                "auth": auth,
            }
        }
    });
    let docker_config = serde_json::to_vec(&docker_config).map_err(|error| SdkError::Body {
        reason: error.to_string(),
    })?;
    let secret = serde_json::json!({
        "apiVersion": "v1",
        "kind": "Secret",
        "type": DOCKER_CONFIG_JSON_TYPE,
        "metadata": {
            "name": request.name,
            "namespace": request.namespace,
            "labels": {"cua.ai/registry-secret": "true"},
        },
        "data": {DOCKER_CONFIG_JSON_KEY: STANDARD.encode(docker_config)},
    });
    serde_json::to_vec(&secret).map_err(|error| SdkError::Body {
        reason: error.to_string(),
    })
}

fn json_request(method: &str, url: url::Url, body: Option<Vec<u8>>) -> HttpRequest {
    HttpRequest {
        method: method.into(),
        url: url.into(),
        headers: vec![
            HttpHeader {
                name: "accept".into(),
                value: JSON_CONTENT_TYPE.into(),
            },
            HttpHeader {
                name: "content-type".into(),
                value: JSON_CONTENT_TYPE.into(),
            },
        ],
        body,
        timeout_secs: None,
        max_response_bytes: Some(1 << 20),
    }
}

